crates/vb_storage/src/executor/issuance_tests.rs:10: 
crates/vb_storage/src/executor/issuance_tests.rs:11: // Case 1: Pure prepare across policies produces empty sequence.
crates/vb_storage/src/executor/issuance_tests.rs:12: #[test]
crates/vb_storage/src/executor/issuance_tests.rs:13: fn prepare_produces_no_sequence() -> TestResult {
crates/vb_storage/src/executor/issuance_tests.rs:14:     for policy in [
crates/vb_storage/src/executor/issuance_tests.rs:15:         &RuntimePolicy::Strict,
crates/vb_storage/src/executor/issuance_tests.rs:16:         &RuntimePolicy::Journaled,
crates/vb_storage/src/executor/issuance_tests.rs:17:         &RuntimePolicy::Relaxed,
crates/vb_storage/src/executor/issuance_tests.rs:18:     ] {
crates/vb_storage/src/executor/issuance_tests.rs:19:         let fixture = PackedFixture::new()?;
crates/vb_storage/src/executor/issuance_tests.rs:20:         let (_dir, journal) = open_test_journal()?;
crates/vb_storage/src/executor/issuance_tests.rs:21:         assert_eq!(read_counter(&journal)?, None);
crates/vb_storage/src/executor/issuance_tests.rs:22:         assert!(journal.list_artifacts()?.is_empty());
crates/vb_storage/src/executor/issuance_tests.rs:23:         let artifact = fixture.prepare(*policy)?;
crates/vb_storage/src/executor/issuance_tests.rs:24:         assert_eq!(artifact.accepted_at_seq.get(), 0);
crates/vb_storage/src/executor/issuance_tests.rs:25:         let restored = fixture.catalog.verify_artifact(&artifact, *policy)?;
crates/vb_storage/src/executor/issuance_tests.rs:26:         assert_eq!(&restored, &fixture.workflow);
crates/vb_storage/src/executor/issuance_tests.rs:27:         assert_eq!(read_counter(&journal)?, None);
crates/vb_storage/src/executor/issuance_tests.rs:28:         assert!(journal.list_artifacts()?.is_empty());
crates/vb_storage/src/executor/issuance_tests.rs:29:     }
crates/vb_storage/src/executor/issuance_tests.rs:30:     Ok(())
crates/vb_storage/src/executor/issuance_tests.rs:31: }
crates/vb_storage/src/executor/issuance_tests.rs:32: 
crates/vb_storage/src/executor/issuance_tests.rs:33: // Case 2a: Strict policy submit returns sequence 1.
crates/vb_storage/src/executor/issuance_tests.rs:34: #[test]
crates/vb_storage/src/executor/issuance_tests.rs:35: fn strict_submit_sequence_one() -> TestResult {
crates/vb_storage/src/executor/issuance_tests.rs:36:     let fixture = PackedFixture::new()?;
