fn check_persist_precommit(fixture: &PackedFixture, policy: RuntimePolicy) -> TestResult {
    let fresh = open_test_journal()?;
    fresh.1.fail_next_persist_for_test();
    let result = fixture.submit(&fresh.1, policy);
    assert!(
        matches!(
